        }
        case 'think': {
          const t = d.think || d.text || ''
          if (t) updStream(p => ({ ...p, think: p.think + t, thinkDone: false }))
          break
        }
        case 'think_end':
          updStream(p => ({ ...p, thinkDone: true }))
