        case 'tool':
          updStream(p => {
            const argsText = typeof d.args === 'object' && d.args !== null
              ? (d.args.command || d.args.path || JSON.stringify(d.args))
              : String(d.args || '')
            return { ...p, tools: [...p.tools, { id: d.id || 't' + Date.now(), name: d.name || 'tool', argsText, output: '', running: true, status: 'running' }] }
