import json,glob,os,collections
files=glob.glob(os.path.expanduser('~/.pi/agent/sessions/**/*.jsonl'),recursive=True)
findings=[]
for f in files:
 try:
  calls=[]
  for ln,line in enumerate(open(f,encoding='utf-8'),1):
   try:o=json.loads(line)
   except:continue
   m=o.get('message') or {}
   if m.get('role')=='assistant':
    for b in m.get('content') or []:
     if isinstance(b,dict) and b.get('type')=='toolCall': calls.append((ln,b.get('id'),b.get('name'),json.dumps(b.get('arguments'),sort_keys=True,ensure_ascii=False)))
  ids=collections.Counter(x[1] for x in calls if x[1])
  dupids=[(i,n) for i,n in ids.items() if n>1]
  same=[]
  for a,b in zip(calls,calls[1:]):
   if a[2:] == b[2:]: same.append((a[0],b[0],a[1],b[1],a[2]))
  if dupids or same: findings.append((f,len(calls),dupids[:5],same[:5]))
 except: pass
print('files_scanned',len(files),'files_with_duplicate_evidence',len(findings))
for f,n,d,s in findings[-20:]: print(os.path.basename(f),'calls',n,'dup_ids',d,'adjacent_same',s)
PY

